import {holeTargets,progressAt,delayWindow,delayIncident} from './traffic-model.js';
import {mapPoints} from './bandon-model.js';
export const clock=n=>`${String(Math.floor(n/60)%24).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
export function situation(minutes,choice='auto'){return choice==='auto'?(delayIncident(minutes).active?'queue':'normal'):choice;}
export function groupsAt(minutes,choice='auto',target=245,configuredTargets){const targets=configuredTargets||holeTargets([],target),incident=delayIncident(minutes,choice,targets),state=choice==='auto'?(incident.active?'queue':'normal'):choice,groups=[];for(let id=4;id<=11;id++){const elapsed=Math.max(0,minutes+(8-id)*10),scheduled=minutes<(id-8)*10;let progress=scheduled?.02:progressAt(elapsed,targets);if((choice==='auto'||choice==='queue')&&id===4){const before=targets.slice(0,4).reduce((a,b)=>a+b,0),start=before+targets[4]*.8,end=before+targets[4]+8;if(elapsed>=start&&elapsed<=end)progress=4+.8+.2*(elapsed-start)/(end-start);else if(elapsed>end)progress=choice==='queue'?4.98:progressAt(elapsed-8,targets);}if(state==='gap'&&id===8)progress=Math.max(.04,progress-.45);if(state==='stale'&&id===8)progress=.06;const desired=progress;if(groups.length&&!scheduled)progress=Math.min(progress,groups.at(-1).progress-.08);progress=Math.min(17.98,Math.max(.02,progress));const hole=Math.floor(progress)+1,before=targets.slice(0,hole-1).reduce((a,b)=>a+b,0);groups.push({id,hole,fraction:progress%1,progress,stale:state==='stale'&&id===8,status:state,waiting:progress<desired-.02,holeTarget:targets[hole-1],holeElapsed:id===4&&hole===5?Math.max(0,elapsed-before):Math.max(0,(progress%1)*targets[hole-1]),elapsed,incident:incident.active?incident:null});}return groups;}

export function boundsForHole(hole){const col=(hole-1)%6,row=Math.floor((hole-1)/6);return [[-row*950, col*590],[800-row*950,450+col*590]];}
export function atlasPosition(group){const bounds=boundsForHole(group.hole),p=mapPoints(group.hole,4);const x=p.tee.x+(p.pin.x-p.tee.x)*group.fraction,y=p.tee.y+(p.pin.y-p.tee.y)*group.fraction;return [bounds[0][0]+800-y,bounds[0][1]+x];}
export function roundBrief(minutes,choice='auto'){const state=situation(minutes,choice);return {state,title:{normal:'Your group is on pace',queue:'Traffic ahead · waiting is okay',gap:'A gap is opening ahead',stale:'Your group’s tracking is paused'}[state],message:{normal:'Keep comfortable contact with the group ahead. Tap any group to see its progress.',queue:'A queue is forming in this demo. Your finish estimate has moved later; no pace penalty applies.',gap:'There is room ahead in this scenario. Please keep pace when safe.',stale:'The demo marker is frozen at its last observation. No pace warning is issued.'}[state],finish:clock(510+245+(state==='queue'?18:state==='gap'?10:0))};}
